import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"RFC-0019: Home Assistant Allowlisted-Action Capability Mapping","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-os/blob/main/docs/rfcs/0019-home-assistant-allowlisted-action-capability-mapping.md"},"headers":[],"relativePath":"sovereign-os/rfcs/0019-home-assistant-allowlisted-action-capability-mapping.md","filePath":"sovereign-os/rfcs/0019-home-assistant-allowlisted-action-capability-mapping.md"}'),n={name:"sovereign-os/rfcs/0019-home-assistant-allowlisted-action-capability-mapping.md"};function s(c,e,r,l,d,h){return o(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="rfc-0019-home-assistant-allowlisted-action-capability-mapping" tabindex="-1">RFC-0019: Home Assistant Allowlisted-Action Capability Mapping <a class="header-anchor" href="#rfc-0019-home-assistant-allowlisted-action-capability-mapping" aria-label="Permalink to &quot;RFC-0019: Home Assistant Allowlisted-Action Capability Mapping&quot;">​</a></h1><p><strong>Status:</strong> Accepted (2026-08-21, project creator) <strong>Author:</strong> Project creator and Claude <strong>Created:</strong> 2026-08-21 <strong>Reviewers:</strong> Project creator <strong>Target phase:</strong> <a href="./../roadmap/01-2-local-conversation-capabilities.html">Milestone 01.2, Local Conversation and Capabilities</a> §11, Following Vertical Slice; <a href="./../../ROADMAP.html">ROADMAP.md</a> Milestone 5, Home Automation Integration <strong>Supersedes:</strong> None</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Registers one mutating Home Assistant capability, <code>home_assistant.set_entity_state</code>, against <a href="./0003-capability-contract.html">RFC-0003</a>&#39;s contract — the roadmap&#39;s second Home Assistant slice (&quot;propose allowlisted actions... require confirmation according to risk&quot;), building on <a href="./0018-home-assistant-read-only-capability-mapping.html">RFC-0018</a> (Accepted)&#39;s read-only slice rather than replacing it. Structurally this is <code>mutating</code>/<code>external</code>, which RFC-0003&#39;s table already fixes as <code>confirmation: required</code> — the same tier <code>read_only</code>/<code>external</code> capabilities already sit at, since RFC-0003&#39;s table has no tier above <code>required</code>. This RFC does not invent one. Instead it answers &quot;confirmation according to risk&quot; the way RFC-0018 answered its own hardest question: by being deliberately conservative about <em>scope</em>, not by inventing a new confirmation <em>mechanism</em> RFC-0003 doesn&#39;t have. Concretely: this slice covers exactly two Home Assistant domains, <code>light</code> and <code>switch</code> — the lowest-consequence, fully-reversible, no-numeric-range action domains Home Assistant exposes — and explicitly excludes locks, climate, covers, cameras, and every other domain as out of scope for a future RFC once this narrower slice has real usage behind it, mirroring how RFC-0018 itself shipped read-only before any mutating capability at all.</p><p>This RFC also has to resolve two things RFC-0018 didn&#39;t need to: a second, independent allowlist and policy toggle for <em>control</em>, distinct from the <em>read</em> allowlist and toggle RFC-0018 already built (so enabling reading never silently enables controlling — the same principle RFC-0018 itself used to keep Home Assistant separate from <code>web.search</code>); and the mutating-capability confirmation UX RFC-0003 and RFC-0004 both explicitly named as this project&#39;s first real design question in that area, since no mutating capability has existed until now.</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p><a href="./../roadmap/01-2-local-conversation-capabilities.html">docs/roadmap/01-2-local-conversation-capabilities.md</a> §11 names this slice directly: &quot;3. propose allowlisted actions; 4. require confirmation according to risk; and 5. preserve deterministic authorization outside the model.&quot; <a href="./../../ROADMAP.html">ROADMAP.md</a>&#39;s Milestone 5 entry: &quot;Later slices may propose allowlisted actions, but deterministic policy outside the model must authorize them and require confirmation according to risk. The model never receives unrestricted Home Assistant, shell, Docker, or network access.&quot; <a href="./../roadmap/00-master-plan.html">docs/roadmap/00-master-plan.md</a>&#39;s Home Assistant Integration section adds: &quot;Add controlled actions. Require confirmation for sensitive actions.&quot; Both <a href="./0003-capability-contract.html">RFC-0003</a> and <a href="./0004-ai-capability-invocation.html">RFC-0004</a> explicitly deferred the one open question standing between &quot;read-only Home Assistant exists&quot; and &quot;allowlisted actions exist&quot; to whichever RFC ships the first mutating capability — RFC-0003&#39;s own Unresolved Questions: &quot;The exact mutating-capability confirmation UX (beyond &#39;required&#39;) is deferred to Milestone 5, when a mutating capability first actually ships.&quot; RFC-0004&#39;s own Non-Goals: &quot;Mutating-capability confirmation UX beyond what RFC-0003 already deferred to Milestone 5 — no mutating capability exists yet for this RFC to design a flow around.&quot; That capability is this RFC&#39;s.</p><p>Three concrete gaps block a Home Assistant action capability from being buildable, none hypothetical:</p><ol><li><strong>No mutating capability has ever been registered in this project.</strong><code>system.health</code>, both Pi-hole capabilities, <code>web.search</code>/<code>web.fetch</code>, and RFC-0018&#39;s own <code>home_assistant.list_entities</code>/<code>get_history</code> are all <code>read_only</code>. RFC-0003&#39;s Confirmation Model table already has a <code>mutating</code>/<code>external</code> row (<code>required</code>, same as <code>read_only</code>/<code>external</code>) but nothing has ever exercised it — the executor&#39;s stage-4 confirmation gate is unit-tested against synthetic fixture capabilities (<code>tests/test_capabilities.py</code>), never a real mutating capability&#39;s real implementation.</li><li><strong>No control-specific authorization exists.</strong> RFC-0018&#39;s entity allowlist (<code>allowlisted_entities</code> in <code>home-assistant.json</code>) governs what the model may <em>read</em> — it says nothing about what it may <em>change</em>, and reusing it directly for control would mean a household opting into &quot;the assistant can tell me the kitchen light is on&quot; also silently grants &quot;the assistant can turn it off,&quot; collapsing two different consent decisions into one. RFC-0018&#39;s own <code>policy_key</code> generalization (<code>sovereign_capabilities.Capability</code>) was built specifically to keep independent toggles independent (that RFC&#39;s own words: &quot;enabling web search must not silently also enable Home Assistant&quot;) — the same principle now applies one level deeper, within Home Assistant itself.</li><li><strong>No mutating-capability confirmation UX exists</strong>, by RFC-0003/RFC-0004&#39;s own explicit, on-the-record deferral quoted above. A confirmation prompt that discloses &quot;will read <code>light.kitchen</code>&#39;s state&quot; and one that discloses &quot;will turn <code>light.kitchen</code> <strong>off</strong>, in your actual home, right now&quot; are not the same kind of decision, even though RFC-0003&#39;s structural table classifies both as <code>required</code>. Nothing in this project has designed what that disclosure should say, whether a successful action needs a different receipt than a successful read, or how a no-op (proposing to turn on a light that&#39;s already on) should be represented.</li></ol><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ul><li>Register <code>home_assistant.set_entity_state</code> against RFC-0003&#39;s contract: schema, classification (<code>mutating</code>/<code>external</code>/<code>required</code>, structural), and bounds.</li><li>Scope this slice to exactly the domains whose actions are fully reversible and carry no numeric, safety, or privacy risk — deferring every other domain to a named future RFC rather than attempting a general Home Assistant control surface in one pass.</li><li>Design the control-specific allowlist and its relationship to RFC-0018&#39;s existing read allowlist (a subset, never a superset), and the control-specific policy toggle&#39;s relationship to RFC-0018&#39;s existing read toggle (independent, not shared).</li><li>Design the mutating-capability confirmation disclosure and receipt — the concrete answer to RFC-0003/RFC-0004&#39;s shared deferral — reusing RFC-0017&#39;s confirmation wire format unchanged, the same way RFC-0018 already proved that format capability-agnostic.</li><li>Define idempotent behavior for a proposal that requests a state the entity is already in, so &quot;turn off the kitchen light&quot; when it&#39;s already off is a normal, narrated success, not an error or a wasted Home Assistant request.</li></ul><h2 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-Goals&quot;">​</a></h2><ul><li><strong>Every Home Assistant domain except <code>light</code> and <code>switch</code>.</strong> Locks, climate, covers (garage doors, blinds), cameras, alarm control panels, and every other domain are explicitly out of scope. This is the concrete, scope-level answer to &quot;confirmation according to risk&quot; — see Summary and Proposal, Domain Scope. A future RFC can extend this capability&#39;s domain set (or add domain-specific capabilities) once this narrower slice has real usage and audit-log evidence behind it, the same &quot;revisit once real usage exists&quot; posture RFC-0017 already took toward SearXNG&#39;s upstream engine list.</li><li><strong>Any service call beyond on/off.</strong> No brightness, color, temperature, position, or other numeric/enumerated service data — <code>state: &quot;on&quot; | &quot;off&quot;</code> is the entire action surface this RFC defines. Dimming and color control are real, anticipated future work, not designed here.</li><li><strong>A generic <code>call_service</code> passthrough</strong> taking <code>domain</code>/<code>service</code>/ <code>service_data</code> as free arguments. Rejected outright, not merely deferred: RFC-0004/the milestone plan&#39;s own Exit Criteria bar (&quot;no model output can directly invoke... Home Assistant... or unrestricted network access&quot;) already rules this out, and this project&#39;s own precedent (RFC-0006, RFC-0017, RFC-0018) is small, named, bounded capabilities per real use case, never one parameterized general-purpose tool.</li><li><strong>Amending RFC-0003&#39;s Confirmation Model table</strong> to add a tier above <code>required</code>, or any per-capability confirmation strength. Real tension is named directly (Proposal, Confirmation Disclosure) but resolving it the way this RFC does — narrowing <em>scope</em>, not inventing a new <em>mechanism</em> — is deliberately chosen over an RFC-0003 amendment, for the same reason RFC-0018 declined to amend RFC-0003&#39;s <code>local</code>/<code>external</code> axis rather than resolve its own tension in scope/design instead.</li><li><strong>Console&#39;s actual settings UI</strong> for the control toggle and the controllable-entities picker — this RFC fixes the API contract (an extension of RFC-0018&#39;s existing <code>home-assistant.json</code>/ <code>/api/v1/conversation/home-assistant</code> surface) that UI depends on, matching how RFC-0018 fixed its own API contract before its Console UI was built in a separate follow-up pass. Named in Acceptance Criteria as necessary follow-up, not built here.</li><li>Real-hardware qualification — depends on the same external dependency RFC-0018 already disclosed (a real Home Assistant instance reachable on the household network), unresolved as of this RFC&#39;s writing.</li></ul><h2 id="context-and-evidence" tabindex="-1">Context and Evidence <a class="header-anchor" href="#context-and-evidence" aria-label="Permalink to &quot;Context and Evidence&quot;">​</a></h2><ul><li><a href="./../roadmap/01-2-local-conversation-capabilities.html">docs/roadmap/01-2-local-conversation-capabilities.md</a> §11 and <a href="./../../ROADMAP.html">ROADMAP.md</a> Milestone 5, and <a href="./../roadmap/00-master-plan.html">docs/roadmap/00-master-plan.md</a>&#39;s Home Assistant Integration section — the direct source of this RFC&#39;s scope, quoted in Problem above.</li><li><a href="./0003-capability-contract.html">RFC-0003</a> (Accepted): the <code>mutating</code>/<code>external</code> → <code>required</code> row already exists in the Confirmation Model table (derived structurally, same as <code>read_only</code>/<code>external</code>); its own Unresolved Questions explicitly name &quot;the exact mutating-capability confirmation UX&quot; as this RFC&#39;s job.</li><li><a href="./0004-ai-capability-invocation.html">RFC-0004</a> (Accepted): the confirmation flow&#39;s architecture (pending decision surfaced, single-use time-bounded token, model never sees the token, denial is a normal audited outcome) is fixed and reused unchanged; its own Non-Goals name the same deferral RFC-0003 does.</li><li><a href="./0017-web-search-and-fetch-capability-mapping.html">RFC-0017</a> (Accepted): the confirmation pause/resume wire format (<code>pending_confirmation</code>/<code>confirmation</code> fields on <code>POST /api/v1/conversation/message</code>), already proven capability-agnostic once by RFC-0018&#39;s own reuse, reused unchanged again here.</li><li><a href="./0018-home-assistant-read-only-capability-mapping.html">RFC-0018</a> (Accepted): the entity allowlist and <code>policy_key</code>/<code>policy_check</code> generalization this RFC builds directly on; <code>home-assistant.json</code>&#39;s existing shape (<code>enabled</code>, <code>base_url</code>, <code>allowlisted_entities</code>) and the credential-storage design, both extended rather than replaced here.</li><li><code>image-builder/sovereign/appliance/lib/sovereign_homeassistant.py</code>, read directly: <code>read_config()</code>/<code>write_config()</code>/<code>policy_fields()</code>, <code>fetch_all_states()</code>, and the <code>_get()</code> HTTP client this RFC&#39;s own implementation would extend with a <code>_post()</code> counterpart for Home Assistant&#39;s service-call endpoint.</li><li>Home Assistant&#39;s REST API, confirmed directly against its own developer documentation (<code>developers.home-assistant.io/docs/api/rest/</code>): <code>POST /api/services/&lt;domain&gt;/&lt;service&gt;</code> accepts a JSON body (commonly <code>{&quot;entity_id&quot;: &quot;...&quot;}</code>, plus service-specific fields this RFC doesn&#39;t use) and returns a list of entities whose state changed while the service executed (each with <code>entity_id</code>/<code>state</code>/<code>attributes</code>/ <code>last_changed</code>) — HTTP 200 on success, 400 if <code>return_response</code> semantics are used incorrectly (this RFC never sets <code>return_response</code>). <code>light.turn_on</code>/<code>light.turn_off</code> and <code>switch.turn_on</code>/<code>switch.turn_off</code> are Home Assistant&#39;s own standard, long-documented services for exactly the on/off action this RFC defines — no service discovery or per-install service-catalog lookup is needed for a fixed, known service pair per domain.</li><li>Console&#39;s existing Home Assistant page (<code>image-builder/sovereign/appliance/console/index.html</code>), read directly: the pre-existing &quot;Capability scope&quot; preview panel already models authorization as per-domain grants (Lights/Climate shown granted, Locks/Cameras shown not granted) — evidence this project&#39;s own earlier design work already anticipated domain-level risk differentiation for actions, which this RFC&#39;s Domain Scope section makes real for exactly two of those domains.</li></ul><h2 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h2><h3 id="domain-scope" tabindex="-1">Domain Scope <a class="header-anchor" href="#domain-scope" aria-label="Permalink to &quot;Domain Scope&quot;">​</a></h3><p>This slice&#39;s action surface is <code>light</code> and <code>switch</code> only, enforced at three independent points (config write, policy check, and service-call construction — see below), not merely by convention:</p><ul><li><strong>Why these two domains and no others.</strong> Both are binary (<code>on</code>/<code>off</code>), immediately and fully reversible (turning a light back on undoes turning it off, with no partial or accumulating state), carry no numeric range to validate or misconfigure, and have no safety implication beyond ordinary light/appliance use. Locks and alarm panels are safety- and security-critical (RFC-0018&#39;s own Security and Privacy section already named <code>lock</code>/<code>alarm_control_panel</code> as entities a household would reasonably never even allowlist for <em>reading</em>, let alone controlling). Climate has a numeric range that&#39;s genuinely risky to get wrong (a mis-set target temperature is a real comfort/ equipment-wear problem) and household-specific bounds this RFC has no evidence to set safely. Covers (garage doors) and cameras carry physical-security and privacy implications neither reading nor a simple on/off model addresses. All are real, anticipated future capabilities — deliberately not designed here.</li><li><strong>Enforced independently at three separate points, not derived once and trusted downstream — found to matter concretely, not just in principle, during this RFC&#39;s own review (see below).</strong><ol><li><p><code>write_config()</code> (extended below) rejects any <code>controllable_entities</code> entry whose domain (the <code>entity_id</code>&#39;s own dot-prefix, e.g. <code>light</code> in <code>light.kitchen</code> — the same derivation RFC-0018&#39;s <code>fetch_all_states</code>/<code>make_list_entities_implementation</code> already use) is not <code>light</code> or <code>switch</code>, regardless of how the entry was submitted — a raw API call bypassing any future Console picker gets the identical rejection, not just a UI that happens not to offer the option.</p></li><li><p>The executor&#39;s stage-3 <code>policy_check</code> for this capability re-derives the domain from the proposed <code>entity_id</code> and independently confirms it is <code>light</code>/<code>switch</code> before proceeding — not merely checking list membership and trusting that membership implies a safe domain.</p></li><li><p>The implementation itself, immediately before constructing the <code>POST /api/services/&lt;domain&gt;/...</code> URL, performs the identical independent check a third time and refuses to proceed if it ever fails — see Idempotent No-Ops.</p><p>Points 2 and 3 are not redundant paranoia: this RFC&#39;s own review found that Home Assistant&#39;s <code>climate</code> domain has real, valid <code>climate.turn_on</code>/<code>climate.turn_off</code> services (confirmed against Home Assistant&#39;s own documentation) — meaning if a non-light/switch entity ever reached the service-call construction step (a write-time validation bug, direct config-file corruption, or a future code change that weakens <code>write_config()</code>&#39;s check), deriving <code>domain</code> from <code>entity_id</code> and calling that domain&#39;s <code>turn_on</code>/<code>turn_off</code> would not fail loudly by accident the way an obviously-wrong service name might. <code>lock</code> entities (<code>lock.lock</code>/<code>lock.unlock</code>, not <code>turn_on</code>/<code>turn_off</code>) happen to fail safely if this ever occurred; <code>climate</code> does not. Relying on that asymmetry — safe for some domains, not others, and never by design — is exactly the kind of incidental, unverified safety property this project&#39;s own precedent (RFC-0017&#39;s SSRF policy: &quot;resolve before connecting,&quot; never trust a one-time earlier check) already rejects. The independent re-check at both stage 3 and inside the implementation closes this for real, rather than relying on write-time validation never having a bug.</p></li></ol></li></ul><h3 id="home-assistant-set-entity-state" tabindex="-1"><code>home_assistant.set_entity_state</code> <a class="header-anchor" href="#home-assistant-set-entity-state" aria-label="Permalink to &quot;\`home_assistant.set_entity_state\`&quot;">​</a></h3><ul><li><strong>Purpose:</strong> turn an allowlisted light or switch entity on or off.</li><li><strong>Arguments:</strong> <code>{ &quot;entity_id&quot;: string (required, must be in </code>controllable_entities<code>), &quot;state&quot;: &quot;on&quot; | &quot;off&quot; (required) }</code>. No <code>toggle</code> option — an explicit target state is a clearer instruction for a model to reason about and for a household to review in a confirmation prompt than a relative flip, which requires the reader to already know current state to judge the effect. <code>toggle</code>&#39;s only advantage (not needing to know current state) is not a real constraint here: this capability&#39;s own implementation already reads current state to determine whether the request is a no-op (see Idempotent No-Ops below), so nothing is saved by supporting it.</li><li><strong>Result:</strong> <code>{ &quot;entity_id&quot;: string, &quot;domain&quot;: &quot;light&quot; | &quot;switch&quot;, &quot;previous_state&quot;: string, &quot;new_state&quot;: string, &quot;changed&quot;: bool, &quot;applied_at&quot;: timestamp }</code>. <code>changed: false</code> with <code>previous_state == new_state == state</code> represents a successful no-op (already in the requested state) — a real, narratable outcome (&quot;the kitchen light was already off&quot;), not an error and not indistinguishable from a state change that actually happened.</li><li><strong>Classification:</strong> <code>mutating</code>, <code>external</code> (fixed by RFC-0003), <code>required</code> confirmation (derived, not chosen — RFC-0003&#39;s table has no higher tier for this RFC to reach for).</li><li><strong>Bounds:</strong> <code>timeout_seconds=10</code> (a same-LAN request plus, for a non-no-op call, a real Home Assistant service execution — matching <code>home_assistant.get_history</code>&#39;s own budget for a real backend operation, longer than <code>list_entities</code>&#39;s simple state read), <code>max_result_bytes</code> left at <code>DEFAULT_MAX_RESULT_BYTES</code>, <code>max_invocations_per_turn=1</code>, matching every other registered capability&#39;s default — deliberately not raised for this capability despite a household plausibly wanting to control several lights in one request; RFC-0004&#39;s per-turn round budget (<code>MAX_ROUNDS_PER_TURN = 3</code>) already lets a model propose a second action in a later round of the same turn once the first is resolved, so the real constraint is &quot;one confirmed action at a time,&quot; not &quot;one action per conversation.&quot;</li></ul><h3 id="idempotent-no-ops" tabindex="-1">Idempotent No-Ops <a class="header-anchor" href="#idempotent-no-ops" aria-label="Permalink to &quot;Idempotent No-Ops&quot;">​</a></h3><p>The implementation reads the entity&#39;s current state (via the same <code>GET /api/states/&lt;entity_id&gt;</code> this module&#39;s read-only capabilities already use) before deciding whether to call Home Assistant&#39;s service-call endpoint at all:</p><ul><li><strong>Current state already matches the requested <code>state</code>:</strong> returns <code>changed: false</code> immediately, without calling <code>POST /api/services/&lt;domain&gt;/turn_&lt;state&gt;</code> — a proposal to turn off an already-off light does not generate an unnecessary Home Assistant request, and the model gets an accurate, narratable answer (&quot;already off&quot;) rather than a generic success that implies something happened.</li><li><strong>Current state differs:</strong> first re-derives <code>domain</code> from <code>entity_id</code>&#39;s own prefix and independently asserts it is <code>light</code> or <code>switch</code> — see Domain Scope&#39;s third enforcement point above, not merely trusted from the allowlist membership check — then calls <code>POST /api/services/&lt;domain&gt;/turn_on</code> or <code>.../turn_off</code> with <code>{&quot;entity_id&quot;: entity_id}</code>, then verifies the response&#39;s changed-states list actually contains <code>entity_id</code> with the expected new state before reporting <code>changed: true</code> — Home Assistant returning 200 with an empty or unexpected changed-states list (a real possible outcome: the entity went unavailable between the state read and the service call, or the specific device didn&#39;t actually respond) is treated as a distinct failure (<code>HOME_ASSISTANT_ACTION_NOT_CONFIRMED</code>), not a false success. Reporting &quot;done&quot; for a light that didn&#39;t actually turn off would be a household trusting a receipt that isn&#39;t true — worse than a visible failure the model can narrate honestly.</li><li>This state-then-act sequence is not perfectly race-free (something else could change the entity&#39;s state between the read and the write — a household member using a physical switch, or Home Assistant&#39;s own automations) — disclosed as a known, accepted limitation in Failure and Recovery, not a gap this RFC pretends to close. The verification step above (checking the service call&#39;s own response, not just trusting the read-then-act sequence blindly) is what actually matters for correctness; the no-op check is a request-avoidance optimization, not itself a safety mechanism.</li></ul><h3 id="control-allowlist-and-policy-toggle" tabindex="-1">Control Allowlist and Policy Toggle <a class="header-anchor" href="#control-allowlist-and-policy-toggle" aria-label="Permalink to &quot;Control Allowlist and Policy Toggle&quot;">​</a></h3><p>Extends RFC-0018&#39;s existing <code>home-assistant.json</code> (not a new file — this is the same connection&#39;s config, a further permission dimension on it, unlike the earlier <code>policy.json</code>-vs-<code>home-assistant.json</code> split, which was about genuinely unrelated features):</p><ul><li>Two new fields: <code>control_enabled: bool</code> (default <code>false</code>) and <code>controllable_entities: [string]</code> (default <code>[]</code>).</li><li><strong><code>write_config()</code> (extended) validates, and rejects the whole write if violated:</strong> every entry in <code>controllable_entities</code> must already be present in <code>allowlisted_entities</code> (control is a subset of read — you cannot grant control over something not even opted into reading), and every entry&#39;s domain (derived from its own <code>entity_id</code> prefix) must be <code>light</code> or <code>switch</code> (Domain Scope, enforced here specifically). Both checks are independent of whichever UI or API caller submitted the request.</li><li><strong>A second, distinct executor policy key: <code>home_assistant_control_enabled</code></strong>, not a reuse of RFC-0018&#39;s <code>home_assistant_enabled</code>. Registered via <code>sovereign_capabilities.Capability</code>&#39;s existing <code>policy_key</code> parameter (RFC-0018&#39;s own generalization) — enabling Home Assistant <em>reading</em> must not silently enable Home Assistant <em>control</em>, the identical principle RFC-0018 already established one level up (enabling <code>web.search</code> must not silently enable Home Assistant at all).</li><li><strong><code>policy_fields()</code> (extended)</strong> returns <code>home_assistant_control_enabled</code> and <code>home_assistant_controllable_entities</code> alongside RFC-0018&#39;s existing three fields, for the executor&#39;s stage-3 <code>policy_key</code> gate and this capability&#39;s own <code>policy_check</code> to read.</li><li><strong>A second, distinct <code>policy_check</code> function — not a literal reuse of RFC-0018&#39;s <code>_policy_check</code>.</strong> RFC-0018&#39;s own <code>_policy_check</code> validates against <code>home_assistant_allowlist</code> and raises <code>ENTITY_NOT_ALLOWLISTED</code>; this capability needs to validate against a <em>different</em> policy field (<code>home_assistant_controllable_entities</code>) and raise a <em>different</em> code (<code>ENTITY_NOT_CONTROLLABLE</code>), so it cannot literally be the same function passed to both registrations the way <code>policy_key</code> mechanically can be a shared default. The only piece genuinely shared between the two is the <code>home_assistant_configured</code> check (the connection itself being reachable/set up is a prerequisite for both reading and controlling) — naturally factored into one small helper both <code>policy_check</code> functions call, rather than duplicated, but that&#39;s an implementation-level structuring choice, not an architectural one this RFC needs to fix. Concretely, <code>set_entity_state</code>&#39;s own <code>policy_check</code>: <ol><li>Checks <code>home_assistant_configured</code> (shared helper, unchanged from RFC-0018).</li><li>Checks <code>entity_id in home_assistant_controllable_entities</code> — rejects with <code>ENTITY_NOT_CONTROLLABLE</code> (distinct from RFC-0018&#39;s <code>ENTITY_NOT_ALLOWLISTED</code>, even though the underlying shape of &quot;not on the right list&quot; is similar — a household reading the audit log or a denied-proposal narration should be able to tell &quot;not readable&quot; apart from &quot;readable but not controllable,&quot; since they imply different next steps).</li><li><strong>Defensively also checks <code>entity_id in home_assistant_allowlist</code></strong> (RFC-0018&#39;s own read allowlist field) even though <code>write_config()</code> already enforces <code>controllable_entities ⊆ allowlisted_entities</code> at write time — a mutating, physical-effect capability&#39;s authorization path re-verifying an invariant that&#39;s supposed to already hold, rather than trusting it silently, is proportionate to what this capability can actually do if the invariant is ever wrong.</li><li>Independently re-derives and checks the entity&#39;s domain is <code>light</code>/<code>switch</code> — see Domain Scope&#39;s three-point enforcement above.</li></ol></li></ul><h3 id="confirmation-disclosure-and-receipt" tabindex="-1">Confirmation Disclosure and Receipt <a class="header-anchor" href="#confirmation-disclosure-and-receipt" aria-label="Permalink to &quot;Confirmation Disclosure and Receipt&quot;">​</a></h3><p>Reuses RFC-0017&#39;s <code>pending_confirmation</code>/<code>confirmation</code> wire format on <code>POST /api/v1/conversation/message</code> completely unchanged — no new fields, no new halting behavior, the same mechanism RFC-0018 already proved generalizes to a second capability pair without modification. What this RFC fixes is what a <em>client</em> does with that same generic shape when the pending capability happens to be mutating:</p><ul><li><code>pending_confirmation.arguments</code> already discloses the literal <code>entity_id</code>/<code>state</code> (RFC-0017&#39;s existing &quot;arguments included verbatim and unredacted&quot; behavior — no change needed). What changes is presentation: a mutating proposal&#39;s disclosure copy should name the real-world effect, not just the capability — &quot;Turn <code>light.kitchen</code><strong>off</strong>? This changes something in your home right now, not just what the assistant reads.&quot; — distinct from RFC-0018&#39;s read-only framing (&quot;wants to read your allowlisted Home Assistant entities — this leaves your device&quot;), since the risk being disclosed is materially different (a physical-world effect vs. data leaving the device). This is UI copy, not a wire-format change — Console&#39;s confirmation card (already generic over capability name/arguments per RFC-0018&#39;s own implementation) needs a small, capability-name-keyed copy branch, not new state.</li><li>A successful execution&#39;s receipt (in Console&#39;s chat log, via the same <code>capability_events</code> array every capability already populates) should read as an action completed, not a query answered — e.g. &quot;Turned off the kitchen light&quot; rather than a generic &quot;ran.&quot; <code>changed: false</code> (Idempotent No-Ops) narrates distinctly too — &quot;The kitchen light was already off&quot; — so a household isn&#39;t left wondering whether a no-op silently failed.</li><li>Denial and expiry behave identically to RFC-0017/RFC-0018&#39;s existing handling — a denied or expired mutating proposal is recorded as a denial, never retried automatically, the physical world left exactly as it was (nothing executes until stage 5, unchanged).</li></ul><h2 id="interfaces-and-data-flow" tabindex="-1">Interfaces and Data Flow <a class="header-anchor" href="#interfaces-and-data-flow" aria-label="Permalink to &quot;Interfaces and Data Flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Model proposes home_assistant.set_entity_state(</span></span>
<span class="line"><span>    {&quot;entity_id&quot;: &quot;light.kitchen&quot;, &quot;state&quot;: &quot;off&quot;})    [RFC-0004 flow]</span></span>
<span class="line"><span>    -&gt; RFC-0003 executor stage 2: validate arguments (state in {on, off})</span></span>
<span class="line"><span>    -&gt; stage 3: check policy_key (home_assistant_control_enabled must be</span></span>
<span class="line"><span>       true) -&gt; policy_check (home_assistant_configured, entity_id in</span></span>
<span class="line"><span>       controllable_entities AND in allowlisted_entities, entity_id&#39;s own</span></span>
<span class="line"><span>       domain independently re-derived and confirmed light/switch)</span></span>
<span class="line"><span>    -&gt; stage 3 fails at any check -&gt; rejection appended to context</span></span>
<span class="line"><span>       (CAPABILITY_DISABLED or ENTITY_NOT_CONTROLLABLE), no confirmation</span></span>
<span class="line"><span>       ever generated</span></span>
<span class="line"><span>    -&gt; stage 3 passes, confirmation required (structural, mutating +</span></span>
<span class="line"><span>       external) -&gt; confirmation_store.issue() -&gt; round halts,</span></span>
<span class="line"><span>       pending_confirmation returned [RFC-0017&#39;s existing wire format,</span></span>
<span class="line"><span>       unchanged]</span></span>
<span class="line"><span>    -&gt; Console discloses the real-world effect and prompts for approval</span></span>
<span class="line"><span>    -&gt; user approves -&gt; client resubmits with</span></span>
<span class="line"><span>       {&quot;confirmation&quot;: {&quot;token&quot;: &quot;...&quot;, &quot;approve&quot;: true}}</span></span>
<span class="line"><span>    -&gt; confirmation_store.consume() -&gt; invoke() proceeds through stage 5:</span></span>
<span class="line"><span>       GET /api/states/light.kitchen (current state) -&gt; already &quot;off&quot;?</span></span>
<span class="line"><span>       return changed: false without contacting Home Assistant again |</span></span>
<span class="line"><span>       differs -&gt; re-derive and re-confirm domain is light/switch (third</span></span>
<span class="line"><span>       independent check, see Domain Scope) -&gt; POST /api/services/light/</span></span>
<span class="line"><span>       turn_off {&quot;entity_id&quot;: &quot;light.kitchen&quot;} -&gt; verify light.kitchen</span></span>
<span class="line"><span>       appears in the response&#39;s changed-states list with the expected</span></span>
<span class="line"><span>       state -&gt; changed: true</span></span>
<span class="line"><span>    -&gt; result appended to context as a structured, narratable receipt</span></span></code></pre></div><h2 id="security-and-privacy" tabindex="-1">Security and Privacy <a class="header-anchor" href="#security-and-privacy" aria-label="Permalink to &quot;Security and Privacy&quot;">​</a></h2><ul><li><strong>Every</strong> invocation requires per-invocation user confirmation, structurally, per RFC-0003&#39;s table — no automatic path exists or could exist without an RFC-0003 amendment. A prompt-injected model can cause a proposal, never an execution — identical framing to every prior external/mutating capability this project has shipped.</li><li>Control authorization is strictly narrower than read authorization by construction (<code>controllable_entities ⊆ allowlisted_entities</code>, enforced at write time, not by convention) — a household can never end up able to control an entity it hasn&#39;t already chosen to let the assistant see.</li><li>Domain restriction is enforced independently at three points (write time, policy check, and immediately before the service call itself — Domain Scope), not derived once and trusted downstream. This matters concretely, not just defensively: <code>climate.turn_on</code>/<code>climate.turn_off</code> are real Home Assistant services, so a <code>climate.*</code> entity that ever reached service-call construction would not fail safely by accident — unlike, say, <code>lock.*</code>, which happens to use different service names entirely. A raw, hand-crafted API call attempting to add a <code>lock.*</code> or <code>climate.*</code> entity to <code>controllable_entities</code> is rejected at write time; even a hypothetical bypass of that check is still caught before any request reaches Home Assistant.</li><li>The two independent policy toggles (<code>home_assistant_enabled</code> for reading, <code>home_assistant_control_enabled</code> for acting) mean a household that wants Sovereign to answer &quot;what&#39;s the temperature&quot; without ever being able to act on anything can configure exactly that — read-only access was never a stepping-stone to control access by default.</li><li>Audit events follow RFC-0003 unchanged: the fact of invocation, classification, outcome, and stage reached — never the entity&#39;s before/after state values, which (unlike Pi-hole&#39;s aggregate stats or a search query) directly describes real, currently-observable conditions inside the household&#39;s home. Recording &quot;an action on <code>light.kitchen</code> was proposed and executed&quot; is the operationally useful fact; recording &quot;the kitchen light was on, now off, at 22:14&quot; is real-time household activity data this project&#39;s existing audit-log discipline (RFC-0003, reaffirmed by RFC-0006/RFC-0017/RFC-0018) already declines to persist for less sensitive capabilities than this one.</li><li>This is the first capability whose <em>execution</em> has a real, physical, observable effect on the household, not just an information disclosure. RFC-0004&#39;s untrusted-forever boundary and RFC-0003&#39;s confirmation gate both already exist for exactly this reason (RFC-0002&#39;s original Safety Boundary commitment: &quot;a capability proposal is data, never a command&quot;); this RFC does not add a new safety mechanism so much as it is the first capability where that existing mechanism is actually load-bearing in the way it was designed for.</li></ul><h2 id="failure-and-recovery" tabindex="-1">Failure and Recovery <a class="header-anchor" href="#failure-and-recovery" aria-label="Permalink to &quot;Failure and Recovery&quot;">​</a></h2><ul><li>Home Assistant unreachable, or the pre-action state read fails: fails through RFC-0003&#39;s normal bounded-execution path, audited, narrated as a failure (&quot;I couldn&#39;t reach Home Assistant to check the light&quot;) — the same posture RFC-0018&#39;s own read-only capabilities already take, since this capability&#39;s first step is itself a read.</li><li>The service call succeeds (HTTP 200) but the response&#39;s changed-states list doesn&#39;t confirm the expected entity/state: reported as <code>HOME_ASSISTANT_ACTION_NOT_CONFIRMED</code>, a distinct code from a network failure — the audit trail and any future debugging can tell &quot;Home Assistant accepted the request but didn&#39;t confirm the effect&quot; apart from &quot;the request never reached Home Assistant at all.&quot; Not treated as a silent success under any circumstance (see Idempotent No-Ops).</li><li>A read-then-act race (something else changes the entity&#39;s state between this capability&#39;s own state read and its service call) is a disclosed, accepted limitation, not one this RFC&#39;s design closes — the service-call response verification (above) is what actually catches the case where the intended effect didn&#39;t happen, regardless of why.</li><li>Confirmation token expiry, denial, and a <code>sovereign-conversation</code> process restart while a confirmation is pending all behave identically to RFC-0017/RFC-0018&#39;s existing, already-implemented handling — no new behavior for this capability to define.</li></ul><h2 id="compatibility-and-migration" tabindex="-1">Compatibility and Migration <a class="header-anchor" href="#compatibility-and-migration" aria-label="Permalink to &quot;Compatibility and Migration&quot;">​</a></h2><p>No existing Home Assistant action capability to migrate from. <code>home-assistant.json</code>&#39;s two new fields (<code>control_enabled</code>/<code>controllable_entities</code>) are additive — an existing device with RFC-0018&#39;s three-field config (from before this RFC) reads <code>read_config()</code>&#39;s new fields as their safe defaults (<code>false</code>/<code>[]</code>) via the same fail-safe-to-disabled pattern RFC-0018 already established for a missing/malformed file, not a schema migration. No change to <code>POST /api/v1/conversation/message</code>&#39;s wire format beyond what RFC-0017 already shipped, verified by the existing confirmation-flow test suite continuing to pass unmodified. A future domain-expansion RFC can extend <code>controllable_entities</code>&#39; domain check and this capability&#39;s <code>state</code> enum (or add sibling capabilities for non-binary actions) without redesigning the allowlist/policy-toggle relationship this RFC establishes.</p><h2 id="operations-and-observability" tabindex="-1">Operations and Observability <a class="header-anchor" href="#operations-and-observability" aria-label="Permalink to &quot;Operations and Observability&quot;">​</a></h2><ul><li><code>home-assistant.json</code>&#39;s <code>control_enabled</code>/<code>controllable_entities</code> (like RFC-0018&#39;s own three fields) should be inspectable the same way <code>policy.json</code> already is — a future Console settings panel reads and writes it, not a separate config path.</li><li>The capability audit log records how often <code>set_entity_state</code> is proposed, approved, denied, or rejected by policy/allowlist, and separately how often it resolves as a real state change vs. a no-op — useful for judging whether the confirmation flow&#39;s friction is proportionate for an action capability specifically (a much higher denial rate here than for read-only capabilities might indicate the disclosure copy isn&#39;t landing, or that the allowlist is broader than a household actually wants used).</li></ul><h2 id="testing-strategy" tabindex="-1">Testing Strategy <a class="header-anchor" href="#testing-strategy" aria-label="Permalink to &quot;Testing Strategy&quot;">​</a></h2><ul><li>Contract-level tests mirroring RFC-0018&#39;s own pattern: argument validation rejects a <code>state</code> outside <code>{&quot;on&quot;, &quot;off&quot;}</code> and a malformed <code>entity_id</code>, before any allowlist or network concern is reached.</li><li>Allowlist/domain tests: <code>write_config()</code> rejects a <code>controllable_entities</code> entry not present in <code>allowlisted_entities</code>; rejects an entry whose domain isn&#39;t <code>light</code>/<code>switch</code> even if it <em>is</em> in <code>allowlisted_entities</code> (proving the domain check isn&#39;t merely a consequence of the subset check); accepts a valid light/switch subset.</li><li>Domain-bypass test, adversarial by design (the concrete finding from this RFC&#39;s own review): construct a <code>policy</code> dict directly (bypassing <code>write_config()</code> entirely, the same way RFC-0017&#39;s own SSRF tests mock DNS resolution to bypass the normal request path) with a <code>climate.*</code> or <code>lock.*</code> entity present in <code>home_assistant_controllable_entities</code> — both <code>policy_check</code> and the implementation itself must independently reject it, proving domain enforcement does not depend on <code>write_config()</code> having done its job correctly. Directly verifies the <code>climate.turn_on</code>/<code>climate.turn_off</code> finding above can&#39;t reach a real service call even if the allowlist itself is somehow wrong.</li><li>Policy-gate tests: <code>home_assistant_control_enabled: false</code> (the real default) rejects the capability before confirmation, independent of <code>home_assistant_enabled</code>&#39;s own value — directly verifying enabling reading does not enable control, the same structural proof RFC-0018 required for <code>web_search_enabled</code> vs. <code>home_assistant_enabled</code>.</li><li><code>ENTITY_NOT_CONTROLLABLE</code> tests: an entity present in <code>allowlisted_entities</code> but absent from <code>controllable_entities</code> is rejected at stage 3, distinctly from <code>ENTITY_NOT_ALLOWLISTED</code>.</li><li>Idempotency tests: a request matching current state produces <code>changed: false</code> without any <code>urlopen</code> call to the service-call endpoint (verified the same way RFC-0018&#39;s own tests proved a not-configured/not-allowlisted rejection never reaches the network) — a request differing from current state produces a real service call and <code>changed: true</code>.</li><li>Service-call-not-confirmed tests: a mocked Home Assistant response (200, but the changed-states list omits or contradicts the target entity) produces <code>HOME_ASSISTANT_ACTION_NOT_CONFIRMED</code>, not a false <code>changed: true</code>.</li><li>Confirmation wire-format reuse tests, HTTP-layer, mirroring RFC-0018&#39;s own: a <code>required</code>-confirmation proposal for <code>set_entity_state</code> produces <code>pending_confirmation</code> and no executed result; approval executes exactly once (single-use token, unchanged mechanism); denial records a denial without ever calling Home Assistant.</li><li>Fixture-backed happy-path tests for the full state-check-then-act sequence, without requiring a live Home Assistant instance.</li><li>Real-hardware qualification: named as necessary follow-up, explicitly dependent on the same unresolved external dependency RFC-0018 already disclosed (a real Home Assistant instance reachable on the household network) — this RFC cannot commit to a timeline any more than RFC-0018 could.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives Considered&quot;">​</a></h2><ul><li><strong>Reuse RFC-0018&#39;s single <code>allowlisted_entities</code>/<code>home_assistant_enabled</code> for control too</strong>, rather than a second allowlist and toggle. Rejected: collapses two genuinely different consent decisions (&quot;the assistant may see this&quot; vs. &quot;the assistant may change this&quot;) into one, the exact mistake RFC-0018 itself avoided one level up between <code>web_search_enabled</code> and Home Assistant reading.</li><li><strong>A generic <code>call_service(domain, service, entity_id, service_data)</code> capability</strong>, deferring domain/service/argument restriction entirely to the allowlist. Rejected outright — see Non-Goals; this is structurally the &quot;unrestricted Home Assistant access&quot; the milestone&#39;s own Exit Criteria already forbids, regardless of how tightly the allowlist around it is drawn.</li><li><strong>A <code>toggle</code> action instead of (or alongside) explicit <code>on</code>/<code>off</code> target states.</strong> Rejected: relative actions are harder to reason about and disclose clearly in a confirmation prompt, and this capability already has to read current state for idempotency, so nothing is gained by also supporting a relative form.</li><li><strong>Include <code>climate.set_temperature</code> in this same slice</strong>, since thermostats are common and roughly as &quot;everyday&quot; as lights. Considered and rejected: a numeric target introduces range-validation and equipment-wear considerations this RFC has no household-specific evidence to set safely, unlike a binary on/off action — exactly the kind of consequential decision this project&#39;s RFC process exists to make deliberately once real evidence exists, not fold into a RFC whose own thesis is &quot;start with the domains that don&#39;t need that judgment call at all.&quot;</li><li><strong>Skip the pre-action state read and always call the service, accepting Home Assistant&#39;s own idempotent handling of &quot;turn off an already-off light.&quot;</strong> Considered, since Home Assistant&#39;s own services are themselves idempotent (calling <code>turn_off</code> on an off light is harmless). Rejected because it would make <code>changed</code> always <code>true</code> (or require parsing whether the changed-states list was actually empty to infer a no-op after the fact, which is less reliable than knowing beforehand) and would generate a real Home Assistant request for every proposal regardless of necessity — the state-read-first design gives a more honest <code>changed</code> value and fewer unnecessary requests, at the cost of one extra read call per invocation.</li></ul><h2 id="drawbacks-and-maintenance-cost" tabindex="-1">Drawbacks and Maintenance Cost <a class="header-anchor" href="#drawbacks-and-maintenance-cost" aria-label="Permalink to &quot;Drawbacks and Maintenance Cost&quot;">​</a></h2><ul><li>Two independent allowlists (<code>allowlisted_entities</code>, <code>controllable_entities</code>) and two independent policy toggles inside one config file is real, ongoing complexity beyond RFC-0018&#39;s simpler single-allowlist design — justified by genuinely wanting read and control to be separately, deliberately opted into, not by convenience.</li><li>The domain restriction (<code>light</code>/<code>switch</code> only) means this capability answers a real but narrow slice of &quot;control my home&quot; — a household wanting thermostat or lock control gets nothing from this RFC and has to wait for a future domain-expansion RFC, a real, disclosed scope limitation, not a hidden one.</li><li>The pre-action state read adds a second Home Assistant round trip to every non-no-op invocation (read, then act) — real added latency and request volume versus a naive always-call design, accepted for the correctness and idempotency benefits (Alternatives Considered).</li><li>This is the first capability whose test suite has to prove a negative network property under a <em>mutating</em> classification specifically (that a no-op or a rejected proposal never reaches Home Assistant) — the same discipline RFC-0018&#39;s tests already established for reads, now with higher stakes if it were ever to regress.</li></ul><h2 id="unresolved-questions" tabindex="-1">Unresolved Questions <a class="header-anchor" href="#unresolved-questions" aria-label="Permalink to &quot;Unresolved Questions&quot;">​</a></h2><p>None of the following block acceptance of the capability and design fixed above:</p><ul><li>Whether a future domain-expansion RFC should add new capabilities (<code>home_assistant.set_climate_target</code>, etc.) or extend <code>set_entity_state</code>&#39;s own domain/state enums — likely capability-specific (climate genuinely needs a numeric argument shape this one doesn&#39;t), but not decided here.</li><li>Whether households will want a coarser &quot;control everything I can already read&quot; toggle instead of building <code>controllable_entities</code> one entity at a time — a Console UX question for the follow-up settings page, not an API contract question this RFC needs to resolve.</li><li>Real behavior of the pre-action-state-read-then-act race under genuine concurrent use (a household member flips a physical switch mid-request) — expected to surface as a normal <code>HOME_ASSISTANT_ACTION_NOT_CONFIRMED</code> via the response-verification step, but unverified against a real instance under real concurrent conditions.</li><li>Whether <code>max_invocations_per_turn=1</code> proves too restrictive in practice for a household wanting to control several lights in one request (see Proposal, Bounds, for why this RFC keeps the existing default rather than special-casing it) — needs real usage evidence, not speculation.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h2><ul><li><code>home_assistant.set_entity_state</code> is registered against RFC-0003&#39;s contract with the schema above, classified <code>mutating</code>/<code>external</code>/<code>required</code>.</li><li><code>write_config()</code> rejects a <code>controllable_entities</code> entry not present in <code>allowlisted_entities</code>, and separately rejects an entry whose domain isn&#39;t <code>light</code>/<code>switch</code> even when it is a valid allowlisted entity — both verified directly, not merely documented.</li><li><code>home_assistant_control_enabled: false</code> (the real default on a device that has never touched this configuration) rejects the capability at the policy stage, verified independent of <code>home_assistant_enabled</code>&#39;s own value.</li><li>A proposal for an entity outside <code>controllable_entities</code> is rejected with <code>ENTITY_NOT_CONTROLLABLE</code> before any confirmation is generated and before any Home Assistant request is attempted.</li><li>A <code>controllable_entities</code> entry whose domain is not <code>light</code>/<code>switch</code> is rejected at both <code>policy_check</code> and inside the implementation itself, even when constructed to bypass <code>write_config()</code>&#39;s own check entirely — verified directly against a <code>climate.*</code> entity specifically (this RFC&#39;s own review finding: <code>climate.turn_on</code>/<code>climate.turn_off</code> are real Home Assistant services, so this domain cannot be assumed to fail safely by accident the way an invalid service name might).</li><li>A proposal matching the entity&#39;s current state resolves as <code>changed: false</code> without any request to Home Assistant&#39;s service-call endpoint — verified directly.</li><li>A proposal differing from current state calls the correct <code>light.turn_on</code>/<code>light.turn_off</code>/<code>switch.turn_on</code>/<code>switch.turn_off</code> service and reports <code>changed: true</code> only after verifying the response&#39;s changed-states list confirms the target entity and state.</li><li>A service-call response that doesn&#39;t confirm the expected change produces <code>HOME_ASSISTANT_ACTION_NOT_CONFIRMED</code>, never a false <code>changed: true</code>.</li><li>The confirmation pause/resume flow reuses RFC-0017&#39;s existing <code>pending_confirmation</code>/<code>confirmation</code> fields with no new wire-format code path — verified by extending the existing confirmation test suite to a mutating capability rather than writing a parallel mechanism.</li><li>Existing tests (<code>test_conversation_service.py</code>, <code>test_capabilities.py</code>, RFC-0018&#39;s own Home Assistant tests) continue to pass unmodified, confirming this RFC&#39;s additions are additive to the existing turn loop, executor, and <code>home-assistant.json</code> schema.</li></ul><p>Explicitly <strong>not</strong> required for acceptance, named as necessary follow-up implementation matching this project&#39;s precedent of separating proposal from build-out:</p><ul><li>The capability implementation itself (<code>make_set_entity_state_implementation</code> or equivalent in <code>sovereign_homeassistant.py</code>), the extended <code>write_config()</code>/ <code>policy_fields()</code>, and the extended <code>POST /api/v1/conversation/home-assistant</code> request validation.</li><li>Console&#39;s settings UI for the control toggle and the controllable-entities picker (naturally filtered to light/switch entities already on the read allowlist), and the confirmation-card copy branch for mutating proposals described in Proposal.</li><li>Real-hardware qualification — dependent on a real Home Assistant instance being available on the project&#39;s household network, per Testing Strategy&#39;s disclosed schedule risk, unresolved since RFC-0018.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Accepted (2026-08-21, project creator, reviewed by Claude at the project creator&#39;s direction).</strong> The <code>home_assistant.set_entity_state</code> mapping, its <code>light</code>/<code>switch</code>-only domain scope, the two-allowlist/ two-toggle authorization design, and the idempotent-no-op behavior are accepted as this milestone&#39;s platform contract for its first mutating capability.</p><p>This review found one substantive, safety-relevant gap and fixed it before acceptance rather than after: the original draft claimed domain scope was &quot;enforced at three independent points&quot; but only actually specified one (config write) — the other two were asserted, not designed. Checking whether that mattered in practice (not just in principle) found that it does: Home Assistant&#39;s <code>climate</code> domain has real <code>climate.turn_on</code>/<code>climate.turn_off</code> services, so a non-light/switch entity that ever reached this capability&#39;s service-call construction step — through a write-time validation bug, direct config-file corruption, or a future code change — would not have failed safely by accident the way an invalid service name might have. The design now requires two additional, independent domain re-checks (at the executor&#39;s <code>policy_check</code> stage and immediately before the service-call URL is built), a defensive <code>entity_id in allowlisted_entities</code> re-check alongside the <code>controllable_entities</code> check, and a corrected internal cross-reference (Idempotent No-Ops pointed at Domain Scope with the wrong direction — &quot;below&quot; where it needed &quot;above&quot;). None of this changes the capability&#39;s external contract; all of it is now spelled out precisely enough that Testing Strategy and Acceptance Criteria can actually hold the implementation to it, rather than trusting a single validation layer to never have a bug.</p><p>The Unresolved Questions above are accepted as non-blocking follow-ups, matching this project&#39;s standing precedent for RFC Unresolved Questions sections.</p>`,57)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
